// ═══════════════════════════════════════════════════════════════════════
// FILE MAPPING: data file name → category key
// ═══════════════════════════════════════════════════════════════════════
const FILE_MAP = {
  'math.js': 'math',
  'science.js': 'science',
  'health.js': 'health',
  'engineering.js': 'engineering',
};

// ═══════════════════════════════════════════════════════════════════════
// APPEND TOOLS
// ═══════════════════════════════════════════════════════════════════════
let totalAdded = 0;
const dataDir = path.join(__dirname, '..', 'js', 'data');

Object.entries(FILE_MAP).forEach(([file, key]) => {
  const tools = NEW_TOOLS[key];
  if (!tools || tools.length === 0) return;
  
  const filePath = path.join(dataDir, file);
  let content = fs.readFileSync(filePath, 'utf8');
  
  // Check for duplicate IDs
  const existingIds = new Set();
  const idMatches = content.match(/id:\s*['"]([^'"]+)['"]/g) || [];
  idMatches.forEach(m => existingIds.add(m.match(/['"]([^'"]+)['"]/)[1]));
  
  const newTools = tools.filter(t => !existingIds.has(t.id));
  if (newTools.length === 0) {
    console.log(`  ${file}: all ${tools.length} tools already exist, skipping`);
    return;
  }
  
  // Generate tool code
  let toolCode = '\n\n  // ═══ NEW: ' + newTools.length + ' additional calculators ═══\n\n';
  newTools.forEach((t, i) => {
    toolCode += '  { id: \'' + t.id + '\', name: \'' + t.name + '\', desc: \'' + t.desc + '\', kw: \'' + t.kw + '\',\n';
    toolCode += '    inputs: ' + JSON.stringify(t.inputs).replace(/"/g, '\'') + ',\n';
    toolCode += '    calc: ' + t.calc.toString() + ',\n';
    toolCode += '    steps: ' + t.steps.toString() + ' }' + (i < newTools.length - 1 ? ',' : '') + '\n';
  });
  
  // Insert before ]; (end of array)
  const insertBefore = '];\nif (typeof module';
  const idx = content.lastIndexOf(insertBefore);
  if (idx === -1) {
    console.error(`  ${file}: could not find insertion point`);
    return;
  }
  
  content = content.substring(0, idx) + toolCode + '\n' + content.substring(idx);
  fs.writeFileSync(filePath, content, 'utf8');
  
  totalAdded += newTools.length;
  console.log(`  ${file}: +${newTools.length} new tools (skipped ${tools.length - newTools.length} existing)`);
});

console.log(`\nTotal new tools added: ${totalAdded}`);
console.log('Run: node --check js/data/<file>.js  to verify syntax');
